{
  "states": [
    "Trying",
    "Proceeding",
    "Completed",
    "Confirmed",
    "Terminated"
  ],
  "transitions": [
    {
      "from": "Trying",
      "event": "",
      "action": "pass request to TU",
      "to": "Proceeding"
    },
    {
      "from": "Trying",
      "event": "TU passes 1xx response",
      "action": "send response, enter Proceeding state",
      "to": "Proceeding"
    },
    {
      "from": "Proceeding",
      "event": "TU passes 2xx response",
      "action": "send response, transition to Terminated",
      "to": "Terminated"
    },
    {
      "from": "Proceeding",
      "event": "TU passes 300-699 response",
      "action": "send response, enter Completed state",
      "to": "Completed"
    },
    {
      "from": "Completed",
      "event": "ACK received",
      "action": "",
      "to": "Confirmed"
    },
    {
      "from": "Completed",
      "event": "Timer H fires",
      "action": "indicate transaction failure to TU",
      "to": "Terminated"
    },
    {
      "from": "Completed",
      "event": "Transport Error",
      "action": "inform TU",
      "to": "Terminated"
    },
    {
      "from": "Confirmed",
      "event": "Timer I fires",
      "action": "",
      "to": "Terminated"
    }
